pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeBalance;
        try c.ethBalance() returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint256 returnedBalance;
        try c.ethBalance() returns (uint256 __r) { returnedBalance = __r; } catch { return; }
        uint256 afterBalance;
        try c.ethBalance() returns (uint256 __r) { afterBalance = __r; } catch { return; }
        assertTrue(returnedBalance == beforeBalance && returnedBalance == afterBalance && returnedBalance == address(c).balance);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
